-- Classifies and refines the iOS FAQ set already seeded from the reference material in V4.
-- Corrects FAQ 188, which V9 temporarily classified as Android; IDs and usage history remain intact.
-- No FAQ rows are added or deleted.

UPDATE faqs
SET topic = 'IOS',
    title = CASE
        WHEN id = 188 THEN '[소프트웨어] iPad 강제 재시동 조건과 방법'
        WHEN id BETWEEN 188 AND 195 AND title NOT LIKE '[소프트웨어] %'
            THEN CONCAT('[소프트웨어] ', title)
        WHEN id BETWEEN 196 AND 211 AND title NOT LIKE '[하드웨어] %'
            THEN CONCAT('[하드웨어] ', title)
        WHEN id BETWEEN 212 AND 214 AND title NOT LIKE '[기타] %'
            THEN CONCAT('[기타] ', title)
        ELSE title
    END,
    content = CASE id
        WHEN 188 THEN '기기 잠금 암호를 모르는 상태에서는 강제 재시동을 권장하지 않습니다. 재시동 후 암호를 입력하지 못하면 Wi-Fi에 다시 연결되지 않을 수 있습니다. 암호를 알고 있는 경우에만 진행합니다.\n\n방법: 음량 높이기 버튼을 눌렀다 놓고, 음량 낮추기 버튼을 눌렀다 놓습니다. 화면이 꺼지고 Apple 로고가 나타날 때까지 상단 버튼을 길게 누릅니다.'
        WHEN 189 THEN 'ASM(Apple School Manager) 계정, 앱 설치·배포, 수업 또는 클래스 생성 문의는 빛나는교육(02-6290-1369)에 문의합니다.'
        WHEN 190 THEN '문의 유형에 따라 담당 경로를 구분합니다.\n\n- MDM 설정과 기기 제어: MDM 기술지원센터\n- 기기 파손·침수·공장 초기화 등 유지보수: 케이원 고객지원 또는 기술지원\n- 앱 구매·ASM 계정·수업 및 클래스 생성: 빛나는교육\n\n문제가 일부 기기에만 발생하는지, 학급이나 학교 전체에서 발생하는지 확인하면 기기 문제와 정책·설정 문제를 구분하는 데 도움이 됩니다.'
        WHEN 191 THEN '기기 자체의 잠금 암호를 묻는 경우 케이원 담당 경로로 문의합니다. Apple 계정 암호를 묻는 경우 ASM에서 암호 재설정이 가능한지 확인하고, 방법을 모르면 빛나는교육에 문의합니다.'
        WHEN 192 THEN 'iPad에서 “iPad Unavailable”과 재시도 대기 시간이 표시되면 잠금 암호를 여러 번 잘못 입력해 기기가 잠긴 상태입니다. 잠금 암호를 모르면 MDM에서 암호 초기화가 가능한지 확인하거나 A/S 접수를 안내합니다.'
        WHEN 193 THEN '학생이 임의로 설치할 수 없는 앱은 학교 MDM 관리자가 허용·배포해야 합니다. 필요한 앱의 사용 여부를 학교 정보화 담당자에게 문의합니다.'
        WHEN 194 THEN '학급 전체에서 앱 실행이 느리면 열려 있는 백그라운드 앱을 정리하고 기기를 재시동한 뒤 다시 확인합니다. 같은 증상이 계속되면 기술 부서에 문의합니다.'
        WHEN 195 THEN '학교 Wi-Fi SSID가 바뀐 경우 MDM에서 여러 기기에 설정을 적용할 수 있는지 MDM 기술지원센터에 문의합니다. 일괄 설정을 지원하지 않거나 적용할 수 없으면 각 기기에서 새 네트워크에 연결해야 합니다.'
        WHEN 196 THEN 'iPad 본체가 휘었으면 추가 변형이나 디스플레이 손상을 막기 위해 무리하게 펴지 말고 A/S 점검을 받습니다. 손상 정도에 따라 수리 또는 기기 교체가 결정될 수 있습니다. 사용자 부담 수리 기준은 수리비의 20%, 최대 4만 원이며 최종 처리와 금액은 점검 결과에 따릅니다.'
        WHEN 197 THEN '충전함 대신 정품 어댑터와 케이블을 사용해 충분히 충전한 뒤 전원이 켜지는지 확인합니다. 충전과 재시도 후에도 부팅되지 않으면 A/S 접수를 안내합니다.'
        WHEN 198 THEN '먼저 음량 높이기 버튼을 눌렀다 놓고, 음량 낮추기 버튼을 눌렀다 놓은 뒤 상단 버튼을 길게 눌러 강제 재시동을 시도합니다. 다른 정품 어댑터와 케이블로 15분 이상 충전한 후에도 같은 증상이면 A/S 접수가 필요합니다.\n\n전원이 켜지지 않는 상태에서는 로컬 데이터 백업이 어려울 수 있습니다. 침수 이력이 있으면 충전 단자 손상 가능성도 함께 확인합니다.'
        WHEN 199 THEN 'Apple 로고에서 부팅이 멈추거나 같은 화면이 반복되면 A/S 접수를 안내합니다.'
        WHEN 200 THEN '기기가 멈춰 반응하지 않으면 강제 재시동을 시도합니다. 음량 높이기 버튼을 눌렀다 놓고, 음량 낮추기 버튼을 눌렀다 놓은 뒤 화면이 꺼지고 Apple 로고가 나타날 때까지 상단 버튼을 길게 누릅니다. 증상이 반복되면 A/S 점검을 안내합니다.'
        WHEN 201 THEN '사용 중 전원이 반복해서 켜지고 꺼지면 안정적으로 사용하기 어려운 상태이므로 A/S 접수를 안내합니다.'
        WHEN 202 THEN 'iPadOS 26.2.1 업데이트 후 전원 LED 반응이 늦는 사례는 윈도우형 앱 모드와 관련된 증상으로 안내된 바 있습니다. 설정 > 멀티태스킹 및 제스처에서 [윈도우형 앱]을 끄고 전체 화면 모드로 변경한 뒤 재시동합니다. 증상이 계속되면 A/S 접수를 안내합니다.'
        WHEN 203 THEN 'iPadOS 26.2.1 업데이트 후 포고핀 키보드에서 멈춤이나 지연이 발생하면 설정 > 멀티태스킹 및 제스처에서 [윈도우형 앱]을 끄고 전체 화면 모드로 변경합니다. OS와 타사 키보드 액세서리 간 호환 문제로 안내된 사례이며, 설정 변경 후에도 반복되면 기술 부서에 문의합니다.'
        WHEN 204 THEN '2025년 도입 iPad 키보드 북커버에서 펌웨어 업데이트 후에도 멈춤이 반복되면 A/S 접수 후 담당 엔지니어의 점검을 받습니다. 점검 결과에 따라 교체 여부와 유·무상 처리를 안내합니다.'
        WHEN 205 THEN '안내된 기준상 iPad 4·5차 북커버 키보드는 개선된 펌웨어가 적용된 제품으로 교체 지급됩니다.'
        WHEN 206 THEN '2025년 및 2026년 도입 키보드 북커버는 서로 호환됩니다. 다만 도입 연도별 물품 금액과 공급 업체가 다를 수 있으므로, 다른 연도 제품을 구매·사용하기 전에 학교 담당자와 공급 업체의 승인 및 서비스 적용 여부를 확인합니다.'
        WHEN 207 THEN 'iPad 키보드 북커버는 제품에 따라 연결 방식이 다릅니다.\n\n- 블루투스 방식: 기기와 키보드를 페어링하며 키보드 자체 충전이 필요합니다.\n- 스마트 커넥터 직접 접촉 방식: iPad 측면 또는 후면의 접점과 키보드 접점을 맞춰 연결합니다. 키보드는 iPad에서 전원을 공급받습니다.'
        WHEN 208 THEN '먼저 키보드가 블루투스 방식인지 스마트 커넥터 직접 접촉 방식인지 확인합니다. 가능하면 다른 정상 iPad에 연결해 키보드와 본체 중 문제가 있는 쪽을 나눠 확인합니다.\n\n- 다른 iPad에서도 작동하지 않음: 키보드 이상 가능성이 있어 A/S 접수를 안내합니다.\n- 다른 iPad에서는 작동함: 본체 또는 설정 문제 가능성이 있어 기술지원 경로로 문의합니다.\n\n스마트 커넥터 방식은 iPad 측면 또는 후면의 접점과 키보드 접점이 맞닿았는지 확인합니다.'
        WHEN 209 THEN 'Apple Pencil이 페어링되지 않으면 iPad를 재시동하고, 동일 사양의 다른 어댑터·케이블로도 확인합니다. 다른 정상 Apple Pencil을 연결해 기기와 펜슬 중 어느 쪽 문제인지 비교합니다.\n\n- 다른 펜슬도 연결되지 않음: iPad A/S 접수를 안내합니다.\n- 다른 펜슬은 연결됨: 해당 Apple Pencil 점검 또는 A/S 접수를 안내합니다.'
        WHEN 210 THEN 'Apple Pencil 1세대는 iPad 재시동 후 페어링이 다시 필요할 수 있습니다. iPad의 Lightning 단자에 직접 연결하거나 호환 어댑터와 케이블로 연결해 페어링 안내가 나타나는지 확인합니다. USB-C Apple Pencil은 이 증상과 구분해 모델별 연결 방식을 확인합니다.'
        WHEN 211 THEN '2024년 도입 Apple Pencil을 장기간 사용하지 않으면 배터리가 완전히 방전되어 충전 또는 페어링이 되지 않을 수 있습니다. 장기 미사용 펜슬에 대한 2026년 7월 10일 안내 당시에는 교육청의 별도 지침과 학교 안내에 따라 진행하도록 했습니다. 해당 안내는 시점이 정해진 절차이므로, 서비스 접수 여부는 학교의 최신 공지 기준으로 확인합니다.'
        WHEN 212 THEN '디벗 시리얼 번호 앞에 S가 붙어 있으면 바코드 일괄 스캔 과정에서 추가된 문자일 수 있습니다. 기기 등록이나 수리 접수에 사용할 정식 시리얼은 S를 제외한 번호인지 확인합니다.'
        WHEN 213 THEN 'Google 클래스룸은 교사가 수업 자료와 과제를 공유하고 학생이 확인하거나 제출할 수 있도록 하는 Google 서비스입니다.'
        WHEN 214 THEN '교육청 각인이 있지만 정품 여부가 불분명한 블루투스 펜슬은 각인만으로 납품 제품이라고 확정하지 않습니다. 펜슬의 외형과 각인 사진을 확인해 납품 여부를 관련 부서에 조회합니다.'
        ELSE content
    END
WHERE id BETWEEN 188 AND 214
  AND category_id = (SELECT id FROM faq_categories WHERE name = '유지보수');
